static size_t total;
static unsigned char *pt, *ct;
static unsigned char key[16];
static unsigned char nonce[12];
static int nthreads;

void* worker(void* arg){
    long id=(long)arg;
    size_t chunk = total/nthreads;
    size_t start = id*chunk;
    size_t len = (id==nthreads-1)? total-start : chunk;
    unsigned char iv[16];
    memcpy(iv, nonce, 12);
    uint32_t ctr = 2 + (uint32_t)(start/16);
    iv[12]=(ctr>>24)&0xff; iv[13]=(ctr>>16)&0xff; iv[14]=(ctr>>8)&0xff; iv[15]=ctr&0xff;
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_128_ctr(), NULL, key, iv);
    int outl=0;
    EVP_EncryptUpdate(ctx, ct+start, &outl, pt+start, (int)len);
    EVP_EncryptFinal_ex(ctx, ct+start+outl, &outl);
    EVP_CIPHER_CTX_free(ctx);
    return NULL;
}

void run(int nt, int iters){
    nthreads=nt;
    pthread_t th[64];
    double t0=now();
    for(int it=0;it<iters;it++){
        for(long i=0;i<nt;i++) pthread_create(&th[i],NULL,worker,(void*)i);
        for(int i=0;i<nt;i++) pthread_join(th[i],NULL);
    }
    double t1=now();
    double per=(t1-t0)/iters;
    printf("CTR %zu MB, %d threads: %.3f ms, %.2f GB/s\n", total>>20, nt, per*1e3, total/per/1e9);
}

int main(){
    total = 61440000;
    pt = malloc(total); ct = malloc(total);
    memset(pt, 0x11, total);
    for(int i=0;i<16;i++) key[i]=i;
    for(int i=0;i<12;i++) nonce[i]=i;
    run(1, 5);
    run(2, 5);
    run(4, 5);
    run(6, 5);
    run(12, 5);
    return 0;
}
